{
  "name": "@lazyhands/opencode-memory",
  "version": "0.2.5",
  "description": "Durable cross-session memory for OpenCode: personality and project scopes, learnings, auto-captured guardrails, issue threads, and an injection audit dashboard.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "memory",
    "learnings",
    "guardrails",
    "ai-memory"
  ],
  "license": "MIT",
  "type": "module",
  "engines": {
    "node": ">=24"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lazyhands/opencode-memory.git"
  },
  "homepage": "https://github.com/lazyhands/opencode-memory#readme",
  "bugs": {
    "url": "https://github.com/lazyhands/opencode-memory/issues"
  },
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.tsx",
    "./rpc": "./src/rpc.ts"
  },
  "files": [
    "src",
    "tsconfig.json",
    "config.example.json",
    "CHANGELOG.md"
  ],
  "scripts": {
    "check": "tsc --noEmit",
    "test": "node --test \"test/*.test.ts\""
  },
  "dependencies": {
    "@opencode/plugin": "2.0.29"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.8",
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/client": "2.0.29",
    "@opencode/theme": "2.0.29",
    "@opentui/core": "0.5.17",
    "@opentui/solid": "0.5.17",
    "@types/node": "26.6.5",
    "solid-js": "1.9.12",
    "typescript": "5.8.2"
  },
  "overrides": {
    "seroval": "1.6.9",
    "seroval-plugins": "1.6.9"
  }
}
